import{_ as o}from"./chunks/02.P88t_cDR.js";import{_ as e,o as a,c as r,aa as n}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/nacteni-rozpoctu/01.webp",k=JSON.parse('{"title":"Kompetence pro soupisy","description":"","frontmatter":{"title":"Kompetence pro soupisy","wiki":"cs:performedworks:competences"},"headers":[],"relativePath":"performedworks/competences.md","filePath":"performedworks/competences.md","lastUpdated":1794209661000}'),d={name:"performedworks/competences.md"};function l(s,t,v,p,u,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="kompetence-pro-soupisy" tabindex="-1">Kompetence pro soupisy <a class="header-anchor" href="#kompetence-pro-soupisy" aria-label="Permalink to &quot;Kompetence pro soupisy&quot;">​</a></h1><p>Kdo smí soupisy provedených prací zadávat a kdo schvalovat, určují dvě věci: firma, ke které je uživatel v projektovém týmu přiřazen, a kompetence jeho role. Obojí nastavte dřív, než se v soupisech začne pracovat.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/kompetence">Nastavit, kdo smí soupisy zadávat a schvalovat</a> v Akademii.</p><p>Firmy a role nastavuje v <strong>Nastavení stavby</strong> na záložce <strong>Projektový tým</strong> uživatel s kompetencí <strong>Administrace stavby</strong> nebo <strong>Správa projektového týmu</strong> – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</p><h2 id="kdyz-okno-soupisu-nic-neukazuje" tabindex="-1">Když okno soupisu nic neukazuje <a class="header-anchor" href="#kdyz-okno-soupisu-nic-neukazuje" aria-label="Permalink to &quot;Když okno soupisu nic neukazuje&quot;">​</a></h2><p>Pokud uživatel nemá firmu nebo kompetence nastavené správně, okno soupisu nezobrazí žádné položky a vypíše možné důvody:</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Okno SPP Zhotovitele s hlášením Nelze zobrazit žádné položky rozpočtu a čtyřmi možnými důvody" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Důvod v hlášení</th><th>Co udělat</th></tr></thead><tbody><tr><td>Na stavbě není načtený rozpočet.</td><td>Načtěte rozpočet – viz <a href="/buildary-help-preview/performedworks/budget">Načíst rozpočet</a>.</td></tr><tr><td>Uživatel nemá roli s kompetencemi pro práci v okně.</td><td>Dejte mu roli s kompetencí pro soupisy – viz <a href="#kompetence-roli">Kompetence rolí</a>.</td></tr><tr><td>Uživatel není přiřazený k žádné firmě.</td><td>Vyplňte mu pole <strong>Firma</strong> – viz <a href="#firma-uzivatele">Firma uživatele</a>.</td></tr><tr><td>Firma uživatele není u žádné položky rozpočtu.</td><td>Přiřaďte uživatele k firmě, která v rozpočtu je, nebo opravte firmy v rozpočtu.</td></tr></tbody></table><h2 id="firma-uzivatele" tabindex="-1">Firma uživatele <a class="header-anchor" href="#firma-uzivatele" aria-label="Permalink to &quot;Firma uživatele&quot;">​</a></h2><p>Na záložce <strong>Členové projektu</strong> otevřete člena ikonou tužky a v poli <strong>Firma</strong> vyberte firmu, za kterou na stavbě vystupuje. Podle firmy Buildary určí, čí soupisy uživatel vidí:</p><ul><li>Soupis zhotovitele zadává uživatel přiřazený k firmě zhotovitele.</li><li>Schvalovat soupis zhotovitele může jen uživatel přiřazený k firmě stavebníka.</li><li>U soupisů podzhotovitelů navrhuje uživatel z firmy podzhotovitele a schvaluje uživatel z firmy zhotovitele.</li></ul><p>Uživatel může být přiřazený i k více firmám. Hodí se to, když má pracovat i za jiného účastníka – například stavbyvedoucí zhotovitele zadává soupisy i za některé podzhotovitele. Pak mu přiřaďte i firmy těchto podzhotovitelů a jeho roli dejte kompetenci <strong>Zadání SPP podzhotovitele</strong>.</p><h2 id="role-uzivatele" tabindex="-1">Role uživatele <a class="header-anchor" href="#role-uzivatele" aria-label="Permalink to &quot;Role uživatele&quot;">​</a></h2><p>V poli <strong>Výchozí role v oprávněných osobách</strong> vyberte roli, kterou uživatel na stavbě zastává. Z role plynou jeho kompetence v deníku, v úkolech i v soupisech.</p><h2 id="kompetence-roli" tabindex="-1">Kompetence rolí <a class="header-anchor" href="#kompetence-roli" aria-label="Permalink to &quot;Kompetence rolí&quot;">​</a></h2><p>Kompetence rolí najdete na záložce <strong>Role členů</strong>. U každé role je zaškrtnuté, které kompetence má. V nabídce pohledů vpravo nahoře si můžete zobrazit jen kompetence pro soupisy.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Záložka Role členů v Projektovém týmu s tabulkou kompetencí jednotlivých rolí" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Kompetence</th><th>Co uživateli umožní</th></tr></thead><tbody><tr><td><strong>Zadání SPP zhotovitele</strong></td><td>V okně <strong>SPP Zhotovitele</strong> zadávat <strong>Navržené množství</strong> a <strong>Navrženou cenu</strong> položek, po vrácení k opravě zadávat množství ve sloupci <strong>Změna návrhu</strong> a odeslat zjišťovací protokol na schválení zástupci stavebníka, například technickému dozoru.</td></tr><tr><td><strong>Schvalování SPP zhotovitele</strong></td><td>V okně <strong>SPP Zhotovitele</strong> měnit stav položek, tedy schvalovat a zamítat návrhy zhotovitele, a upravovat <strong>Fakturované množství</strong> a <strong>Fakturovanou cenu</strong>. Smazat všechno čerpání zadané v protokolu. Protokol schválit, vrátit zhotoviteli k opravě a uzavřený protokol znovu odemknout.</td></tr><tr><td><strong>Zadání SPP podzhotovitele</strong></td><td>V okně <strong>SPP Podzhotovitele</strong> zadávat <strong>Navržené množství</strong> a <strong>Navrženou cenu</strong> položek, po vrácení k opravě zadávat množství ve sloupci <strong>Změna návrhu</strong> a odeslat zjišťovací protokol na schválení zhotoviteli.</td></tr><tr><td><strong>Schvalování SPP podzhotovitele</strong></td><td>V okně <strong>SPP Podzhotovitele</strong> měnit stav položek, tedy schvalovat a zamítat návrhy podzhotovitele, a upravovat <strong>Fakturované množství</strong> a <strong>Fakturovanou cenu</strong>. Protokol schválit, nebo vrátit podzhotoviteli k opravě.</td></tr></tbody></table><p>Období soupisů zakládá a upravuje uživatel s kompetencí <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/performedworks/period">Období soupisů</a>.</p><h3 id="vychozi-nastaveni-roli" tabindex="-1">Výchozí nastavení rolí <a class="header-anchor" href="#vychozi-nastaveni-roli" aria-label="Permalink to &quot;Výchozí nastavení rolí&quot;">​</a></h3><p>Ve výchozím nastavení mají kompetence pro soupisy tyto role:</p><table tabindex="0"><thead><tr><th>Role</th><th>Zadání SPP zhotovitele</th><th>Schvalování SPP zhotovitele</th><th>Zadání SPP podzhotovitele</th><th>Schvalování SPP podzhotovitele</th></tr></thead><tbody><tr><td>Administrátor</td><td>ano</td><td>ano</td><td>ano</td><td>ano</td></tr><tr><td>Projektový manažer</td><td>ano</td><td>–</td><td>–</td><td>ano</td></tr><tr><td>Stavbyvedoucí</td><td>ano</td><td>–</td><td>–</td><td>ano</td></tr><tr><td>Stavbyvedoucí podzhotovitele</td><td>–</td><td>–</td><td>ano</td><td>–</td></tr><tr><td>TDS</td><td>–</td><td>ano</td><td>–</td><td>–</td></tr><tr><td>Státní stavební dozor</td><td>–</td><td>ano</td><td>–</td><td>–</td></tr></tbody></table><p>Ostatní výchozí role kompetence pro soupisy nemají. Na běžné stavbě by výchozí nastavení mělo stačit. Administrátor stavby může kompetence rolí upravit nebo vytvořit nové role – viz <a href="/buildary-help-preview/diary/projectteam#role-clenu">Projektový tým: firmy a lidé</a>.</p><h2 id="e-mailova-oznameni" tabindex="-1">E-mailová oznámení <a class="header-anchor" href="#e-mailova-oznameni" aria-label="Permalink to &quot;E-mailová oznámení&quot;">​</a></h2><p>Zda uživateli chodí e-maily o soupisech, nastavíte u každého člena projektového týmu v poli <strong>E-mailové oznámení - Soupisy provedených prací</strong>:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co to znamená</th></tr></thead><tbody><tr><td><strong>Žádné</strong></td><td>E-maily o soupisech nechodí.</td></tr><tr><td><strong>HTML email</strong></td><td>E-maily o soupisech chodí automaticky.</td></tr></tbody></table><p>E-mail přijde, když:</p><ul><li>administrátor stavby založí nové období – všem, kdo smějí soupisy zadávat,</li><li>zhotovitel nebo podzhotovitel odešle protokol na schválení – tomu, kdo ho schvaluje,</li><li>schvalující vrátí protokol k opravě – tomu, kdo soupis zadává,</li><li>schvalující protokol schválí – tomu, kdo soupis zadává; v příloze je zjišťovací protokol v PDF.</li></ul>',28)])])}const z=e(d,[["render",l]]);export{k as __pageData,z as default};
